-- Disposable experiment only. Never register in application migrations.
CREATE TABLE rel_security (user_id TEXT PRIMARY KEY NOT NULL, generation INTEGER NOT NULL DEFAULT 0 CHECK(typeof(generation)='integer' AND generation BETWEEN 0 AND 9007199254740991), disabled INTEGER NOT NULL DEFAULT 0 CHECK(disabled IN (0,1)));
CREATE TABLE rel_approvals (id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL, workspace_id TEXT NOT NULL, member_id TEXT NOT NULL, device_key_digest TEXT NOT NULL, approving_session_id TEXT NOT NULL, approval_login_method TEXT NOT NULL, approved_security_generation INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('approved','revoked')));
-- Witness is assertion DATA, not an access output or production consumer.
CREATE TABLE rel_witness (id TEXT PRIMARY KEY NOT NULL, approval_id TEXT NOT NULL);
CREATE TRIGGER rel_no_unrevoke BEFORE UPDATE ON rel_approvals WHEN OLD.status='revoked' OR NEW.id IS NOT OLD.id OR NEW.user_id IS NOT OLD.user_id OR NEW.workspace_id IS NOT OLD.workspace_id OR NEW.member_id IS NOT OLD.member_id OR NEW.device_key_digest IS NOT OLD.device_key_digest OR NEW.approving_session_id IS NOT OLD.approving_session_id OR NEW.approval_login_method IS NOT OLD.approval_login_method OR NEW.approved_security_generation IS NOT OLD.approved_security_generation BEGIN SELECT RAISE(ABORT,'immutable approval'); END;

CREATE TRIGGER rel_session_delete AFTER DELETE ON sessions WHEN OLD.expires_at >= (CAST(strftime('%s','now') AS INTEGER)*1000 + CAST(substr(strftime('%f','now'),4,3) AS INTEGER)) BEGIN INSERT OR IGNORE INTO rel_security(user_id) VALUES (OLD.user_id); UPDATE rel_security SET disabled=CASE WHEN generation=9007199254740991 THEN 1 ELSE disabled END, generation=CASE WHEN generation<9007199254740991 THEN generation+1 ELSE generation END WHERE user_id=OLD.user_id; UPDATE rel_approvals SET status='revoked' WHERE user_id=OLD.user_id AND status='approved'; END;

CREATE TRIGGER rel_session_update AFTER UPDATE OF id,user_id,impersonated_by,login_method,expires_at ON sessions WHEN OLD.id IS NOT NEW.id OR OLD.user_id IS NOT NEW.user_id OR OLD.impersonated_by IS NOT NEW.impersonated_by OR OLD.login_method IS NOT NEW.login_method OR NEW.expires_at < OLD.expires_at BEGIN INSERT OR IGNORE INTO rel_security(user_id) VALUES (OLD.user_id); UPDATE rel_security SET disabled=CASE WHEN generation=9007199254740991 THEN 1 ELSE disabled END, generation=CASE WHEN generation<9007199254740991 THEN generation+1 ELSE generation END WHERE user_id=OLD.user_id; UPDATE rel_approvals SET status='revoked' WHERE user_id=OLD.user_id AND status='approved';INSERT OR IGNORE INTO rel_security(user_id) VALUES (NEW.user_id); UPDATE rel_security SET disabled=CASE WHEN generation=9007199254740991 THEN 1 ELSE disabled END, generation=CASE WHEN generation<9007199254740991 THEN generation+1 ELSE generation END WHERE user_id=NEW.user_id; UPDATE rel_approvals SET status='revoked' WHERE user_id=NEW.user_id AND status='approved'; END;

CREATE TRIGGER rel_credential_insert AFTER INSERT ON accounts WHEN NEW.provider_id='credential' AND NEW.password IS NOT NULL BEGIN INSERT OR IGNORE INTO rel_security(user_id) VALUES (NEW.user_id); UPDATE rel_security SET disabled=CASE WHEN generation=9007199254740991 THEN 1 ELSE disabled END, generation=CASE WHEN generation<9007199254740991 THEN generation+1 ELSE generation END WHERE user_id=NEW.user_id; UPDATE rel_approvals SET status='revoked' WHERE user_id=NEW.user_id AND status='approved'; END;

CREATE TRIGGER rel_credential_update AFTER UPDATE OF id,user_id,provider_id,password ON accounts WHEN (OLD.provider_id='credential' OR NEW.provider_id='credential') AND (OLD.id IS NOT NEW.id OR OLD.user_id IS NOT NEW.user_id OR OLD.provider_id IS NOT NEW.provider_id OR OLD.password IS NOT NEW.password) BEGIN INSERT OR IGNORE INTO rel_security(user_id) VALUES (OLD.user_id); UPDATE rel_security SET disabled=CASE WHEN generation=9007199254740991 THEN 1 ELSE disabled END, generation=CASE WHEN generation<9007199254740991 THEN generation+1 ELSE generation END WHERE user_id=OLD.user_id; UPDATE rel_approvals SET status='revoked' WHERE user_id=OLD.user_id AND status='approved';INSERT OR IGNORE INTO rel_security(user_id) VALUES (NEW.user_id); UPDATE rel_security SET disabled=CASE WHEN generation=9007199254740991 THEN 1 ELSE disabled END, generation=CASE WHEN generation<9007199254740991 THEN generation+1 ELSE generation END WHERE user_id=NEW.user_id; UPDATE rel_approvals SET status='revoked' WHERE user_id=NEW.user_id AND status='approved'; END;

CREATE TRIGGER rel_credential_delete AFTER DELETE ON accounts WHEN OLD.provider_id='credential' BEGIN INSERT OR IGNORE INTO rel_security(user_id) VALUES (OLD.user_id); UPDATE rel_security SET disabled=CASE WHEN generation=9007199254740991 THEN 1 ELSE disabled END, generation=CASE WHEN generation<9007199254740991 THEN generation+1 ELSE generation END WHERE user_id=OLD.user_id; UPDATE rel_approvals SET status='revoked' WHERE user_id=OLD.user_id AND status='approved'; END;

CREATE TRIGGER rel_user_update AFTER UPDATE OF id,email,email_verified,banned ON users WHEN OLD.id IS NOT NEW.id OR OLD.email IS NOT NEW.email OR (OLD.email_verified=1 AND NEW.email_verified IS NOT 1) OR (COALESCE(OLD.banned,0)=0 AND COALESCE(NEW.banned,0)<>0) BEGIN INSERT OR IGNORE INTO rel_security(user_id) VALUES (OLD.id); UPDATE rel_security SET disabled=CASE WHEN generation=9007199254740991 THEN 1 ELSE disabled END, generation=CASE WHEN generation<9007199254740991 THEN generation+1 ELSE generation END WHERE user_id=OLD.id; UPDATE rel_approvals SET status='revoked' WHERE user_id=OLD.id AND status='approved';INSERT OR IGNORE INTO rel_security(user_id) VALUES (NEW.id); UPDATE rel_security SET disabled=CASE WHEN generation=9007199254740991 THEN 1 ELSE disabled END, generation=CASE WHEN generation<9007199254740991 THEN generation+1 ELSE generation END WHERE user_id=NEW.id; UPDATE rel_approvals SET status='revoked' WHERE user_id=NEW.id AND status='approved'; END;

CREATE TRIGGER rel_user_delete AFTER DELETE ON users BEGIN INSERT OR IGNORE INTO rel_security(user_id) VALUES (OLD.id); UPDATE rel_security SET disabled=CASE WHEN generation=9007199254740991 THEN 1 ELSE disabled END, generation=CASE WHEN generation<9007199254740991 THEN generation+1 ELSE generation END WHERE user_id=OLD.id; UPDATE rel_approvals SET status='revoked' WHERE user_id=OLD.id AND status='approved'; END;

CREATE TRIGGER rel_member_update AFTER UPDATE OF id,user_id,organization_id,role,kind,disabled_at ON members WHEN OLD.id IS NOT NEW.id OR OLD.user_id IS NOT NEW.user_id OR OLD.organization_id IS NOT NEW.organization_id OR OLD.role IS NOT NEW.role OR OLD.kind IS NOT NEW.kind OR OLD.disabled_at IS NOT NEW.disabled_at BEGIN UPDATE rel_approvals SET status='revoked' WHERE status='approved' AND (member_id=OLD.id OR member_id=NEW.id); END;

CREATE TRIGGER rel_member_delete AFTER DELETE ON members BEGIN UPDATE rel_approvals SET status='revoked' WHERE status='approved' AND (member_id=OLD.id); END;

CREATE TRIGGER rel_org_update AFTER UPDATE OF id,require_sso,suspended_at,is_demo ON organizations WHEN OLD.id IS NOT NEW.id OR OLD.require_sso IS NOT NEW.require_sso OR (OLD.suspended_at IS NOT NEW.suspended_at AND NEW.suspended_at IS NOT NULL) OR (COALESCE(OLD.is_demo,0)=0 AND COALESCE(NEW.is_demo,0)<>0) BEGIN UPDATE rel_approvals SET status='revoked' WHERE status='approved' AND (workspace_id=OLD.id OR workspace_id=NEW.id); END;

CREATE TRIGGER rel_org_delete AFTER DELETE ON organizations BEGIN UPDATE rel_approvals SET status='revoked' WHERE status='approved' AND (workspace_id=OLD.id); END;
